package com.luizotavio.academia.controller;
import com.luizotavio.academia.entity.*; import com.luizotavio.academia.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/matriculas") public class MatriculaController { private final MatriculaRepository repo; private final AlunoRepository alunos; public MatriculaController(MatriculaRepository r,AlunoRepository a){repo=r;alunos=a;} @GetMapping public List<Matricula> listar(){return repo.findAll();} @PostMapping("/aluno/{alunoId}") public ResponseEntity<?> criar(@PathVariable Long alunoId){if(repo.existsByAlunoId(alunoId))return ResponseEntity.badRequest().body("Aluno já matriculado"); return alunos.findById(alunoId).map(a->{Matricula m=new Matricula();m.setAluno(a);return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(m));}).orElse(ResponseEntity.notFound().build());} }
